'use strict';
// Isolated visual exploration. No engine imports, accounts, XP writes or persistent storage.
const params=new URLSearchParams(location.search),concept=['a','b','c'].includes(params.get('concept'))?params.get('concept'):'b';
let screen=['home','study','quiz','life','audio','review'].includes(params.get('screen'))?params.get('screen'):'home';
const names={a:'Modern Learning',b:'Gamified Belgium',c:'Premium Interactive'};
const paths={arrow:'M5 12h14m-6-6 6 6-6 6',back:'m14 6-6 6 6 6',book:'M4 4h6a3 3 0 0 1 2 2 3 3 0 0 1 2-2h6v15h-6a3 3 0 0 0-2 2 3 3 0 0 0-2-2H4z M12 6v15',sound:'M4 9h4l5-4v14l-5-4H4z M16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',check:'m5 12 4 4L19 6',x:'m6 6 12 12M6 18 18 6',play:'m9 5 11 7-11 7z',headphones:'M4 14v-3a8 8 0 0 1 16 0v3 M4 12h4v8H4z M16 12h4v8h-4z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2z M9 3v16 M15 5v16',stats:'M4 20V10h4v10m4 0V4h4v16m4 0v-7',game:'M7 8h10l4 9c1 3-3 4-5 1l-1-2H9l-1 2c-2 3-6 2-5-1z M6 11v4m-2-2h4 M16 12h.01M18 14h.01',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',test:'M8 3h8v4H8z M7 5H4v17h16V5h-3 M8 11h8m-8 5h5',pin:'M12 22s8-8 8-14A8 8 0 1 0 4 8c0 6 8 14 8 14z M15 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0',star:'m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z',chevron:'m8 5 7 7-7 7',repeat:'M20 7h-6m6 0V1M4 17h6m-6 0v6 M20 7a9 9 0 0 0-15-3M4 17a9 9 0 0 0 15 3',settings:'M4 7h16M4 17h16 M9 4v6m6 4v6'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[n]||paths.book).split(' M').map((d,i)=>`<path d="${i?'M':''}${d}"/>`).join('')}</svg>`;
const cat='<img class="cat" src="../../app/img/home/hero-cat-v196-320.webp" alt="Наявний котик LerenBe" width="320" height="320">';
const flag='<span class="be-flag" aria-label="Бельгія"></span>';
const route=(s,label,cls='')=>`<button class="${cls}" data-screen="${s}">${label}</button>`;
function dock(){return `<nav class="dock" aria-label="Основна навігація">${[['book','Навчання','home'],['game','Ігри',''],['test','Тести',''],['search','Словник',''],['stats','Прогрес','']].map(([i,t,s])=>`<button ${s?'data-screen="'+s+'"':'data-demo="Цей екран поза межами візуального прототипу."'} ${s==='home'?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav>`}
function header(){return `<header class="header"><a class="brand" href="index.html" aria-label="До вибору концепції"><span class="brand-mark">${icon('book')}</span>LerenBe<span class="version">3.0</span></a><div class="header-right"><span class="xp">${icon('star')}20 XP</span><button class="icon-button" data-demo="Налаштування не підключені в прототипі." aria-label="Налаштування">${icon('settings')}</button></div></header>`}
function course(){return `<button class="course-chip" id="courseButton">${flag}<span>Нідерландська <b>A1.1</b></span><span aria-hidden="true">⌄</span></button>`}
function progress(){return `<div class="course-progress"><div><b>Твій прогрес</b><span>1 / 197 уроків</span></div><div class="track"><i></i></div><small>Наступний крок — частина 2 із 5</small></div>`}
function trail(){return `<div class="trail" aria-label="Навчальний маршрут"><span class="done">${icon('check')}</span><i></i><span class="current">2</span><i></i><span>3</span><i></i><span>4</span><i></i><span>5</span></div>`}
function home(){
 if(concept==='a')return `${header()}<main class="home layout-a"><div class="greeting"><p class="eyebrow">LEARN LANGUAGES. LIVE IN BELGIUM.</p><h1>Маленький урок.<br>Більше впевненості.</h1>${course()}</div><section class="next-card"><div class="card-top"><span class="tag">Твій наступний урок</span><span>5–10 хв</span></div><div class="lesson-head"><div><p class="eyebrow">01 / ЗНАЙОМСТВО</p><h2>Перші слова.<br>Справжні розмови.</h2></div>${cat}</div><p>Привітайся, назви себе й почни розмову.</p>${trail()}${route('study','Продовжити урок '+icon('arrow'),'primary')}${progress()}</section><aside class="home-aside"><a class="life-entry" href="?concept=a&screen=life&frame=1"><img src="assets/station-concept-draft.png" alt="Чернетка сцени зустрічі на вокзалі"><div><span class="eyebrow">LERENBE LIFE</span><h3>Твоя перша<br>зустріч у Бельгії.</h3><span>Спробувати історію ${icon('arrow')}</span></div></a><div class="quiet-row">${icon('headphones')}<div><b>Повтори знайоме</b><p>Слухай і практикуй короткі фрази.</p></div>${route('audio',icon('chevron'),'icon-button')}</div></aside></main>${dock()}`;
 if(concept==='b')return `${header()}<main class="home layout-b"><div class="greeting"><div><p class="eyebrow">ТВІЙ МАРШРУТ У БЕЛЬГІЇ</p><h1>Кожне слово —<br>ще один крок.</h1></div>${course()}</div><section class="adventure-card"><picture><source media="(min-width:768px)" srcset="../../app/img/home/home-hero-desktop.webp"><img class="approved-hero" src="../../app/img/home/home-hero-mobile.webp" alt="Затверджений HERO A/C: Anastasia й Annick у Генті"></picture><span class="location">${icon('pin')}Gent, België</span><div class="adventure-copy"><span class="tag">Твій наступний урок · 5–10 хв</span><h2>Наступна зупинка:<br>знайомство.</h2><p>Навчись починати розмову нідерландською.</p>${route('study','Продовжити урок '+icon('arrow'),'primary')}<div class="chapter-meta"><span>A1.1 · Частина 2/5</span><span>1 урок пройдено</span></div></div>${cat}</section><div class="home-bottom"><section class="journey-mini"><div><h3>Твій маршрут</h3><span>Знайомство</span></div>${trail()}<p>20 XP <span>Перший урок позаду. Рухаймось далі.</span></p></section><a class="life-entry" href="?concept=b&screen=life&frame=1"><img src="assets/station-concept-draft.png" alt="Чернетка LIFE, вокзал"><div><span class="eyebrow">LERENBE LIFE</span><h3>Не просто вчи.<br>Поговори в історії.</h3><span>Перший день у Бельгії ${icon('arrow')}</span></div></a></div></main>${dock()}`;
 return `${header()}<main class="home layout-c"><div class="greeting"><p class="eyebrow">YOUR NEXT MOVE / ТВОЄ НАВЧАННЯ</p><h1>Слова стають<br><em>твоїм життям.</em></h1>${course()}</div><section class="premium-next"><div class="premium-photo"><picture><source media="(min-width:768px)" srcset="../../app/img/home/home-hero-desktop.webp"><img src="../../app/img/home/home-hero-mobile.webp" alt="Затверджений HERO A/C"></picture><span class="photo-caption">GENT / BELGIË</span></div><div class="premium-copy"><span class="tag">НАСТУПНИЙ УРОК</span><div class="large-index" aria-hidden="true">01</div><h2>Почни<br>розмову.</h2><p>Знайомство · A1.1 · 5–10 хв</p>${route('study','Продовжити '+icon('arrow'),'primary')}<div class="premium-meta"><b>20 XP</b><span>Частина 2/5</span></div></div></section><div class="home-bottom"><section class="journey-mini"><h3>Крок за кроком.</h3>${trail()}${progress()}</section><a class="life-entry" href="?concept=c&screen=life&frame=1"><img src="assets/station-concept-draft.png" alt="Чернетка сцени LIFE"><div><span class="eyebrow">INTERACTIVE STORIES</span><h3>Твій перший<br>день у Бельгії.</h3><span>Увійти в історію ${icon('arrow')}</span></div></a></div></main>${dock()}`;
}
function learnHeader(label='Знайомство',count='1 / 5'){return `<header class="learn-header">${route('home',icon('x'),'icon-button')}<div><span>${label}</span><div class="track"><i></i></div></div><span class="question-count">${count}</span></header>`}
function sound(label='Послухати',cls=''){return `<button class="sound ${cls}" data-audio aria-label="${label} — демонстрація стану аудіоплеєра">${icon('sound')}<span>${label}</span></button>`}
function study(){
 return `${learnHeader()}<main class="learning study screen-${concept}"><div class="learning-kicker"><span class="tag">ВИВЧИ НОВЕ СЛОВО</span><span>Нідерландська · A1.1</span></div><section class="word-stage">${concept==='b'?`<div class="study-cat">${cat}<span>Почнемо з простого.</span></div>`:''}<div class="word-content"><p class="word-label">Слово 1 із 5</p><h1 lang="nl">hallo<span class="word-dot">.</span></h1><p class="translation">привіт</p>${sound('Послухати вимову')}</div>${concept==='c'?'<span class="type-index" aria-hidden="true">Aa</span>':''}</section><section class="example"><span class="eyebrow">У РЕАЛЬНІЙ РОЗМОВІ</span><p lang="nl"><b>Hallo</b>, ik ben Anastasia.</p><p>Привіт, я Анастасія.</p></section><div class="learning-footer"><p>${icon('headphones')}Послухай. Повтори. Скажи самостійно.</p>${route('quiz','Зрозуміло, далі '+icon('arrow'),'primary')}</div></main>`;
}
function quiz(){return `${learnHeader('Перевір себе','2 / 5')}<main class="learning quiz screen-${concept}"><div class="quiz-heading"><span class="eyebrow">ОБЕРИ ПЕРЕКЛАД НІДЕРЛАНДСЬКОЮ</span><h1>Як сказати<br><em>«привіт»?</em></h1>${concept==='b'?cat:''}</div><fieldset class="answers"><legend class="sr-only">Варіанти відповіді</legend>${['Goedemorgen','hallo','Dank je wel','Alsjeblieft'].map((x,i)=>`<button class="answer" data-answer="${i}" lang="nl"><span class="answer-index" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span>${x}</span><span class="answer-mark" aria-hidden="true"></span></button>`).join('')}</fieldset><div class="quiz-bottom"><div id="feedback" class="feedback" role="status" aria-live="polite"><p>Обери одну відповідь.</p></div><button class="primary" id="checkAnswer" disabled>Перевірити ${icon('arrow')}</button></div></main>`}
function life(){return `<main class="life life-${concept}"><div class="scene-image"><img src="assets/station-concept-draft.png" alt="Концепт-ілюстрація: Anastasia й Annick зустрічаються на вокзалі, не затверджений ігровий ресурс"></div><header class="life-hud">${route('home',icon('back'),'icon-button')}<div><span class="eyebrow">ПЕРШИЙ ДЕНЬ У БЕЛЬГІЇ</span><b>Gent-Sint-Pieters</b></div><span class="scene-count">2 / 8</span></header><div class="scene-meter" aria-label="Крок 2 із 8"><i></i></div><div class="scene-note">КОНЦЕПТ-ГРАФІКА · НЕ ФІНАЛЬНІ РЕСУРСИ</div><section class="dialogue"><div class="speaker"><span class="speaker-avatar">A</span><div><b>Annick</b><span>Твоя співрозмовниця</span></div>${sound('Послухати')}</div><h1 lang="nl">Hallo! Ben jij<br>Anastasia?</h1><p class="dialogue-translation">Привіт! Ти Анастасія?</p><div class="reply-title"><span>Твоя відповідь</span><span>ОБЕРИ ФРАЗУ</span></div><div class="replies"><button data-reply="correct"><span lang="nl">Ja, ik ben Anastasia.</span><small>Так, я Анастасія.</small>${icon('arrow')}</button><button data-reply="wrong"><span lang="nl">Nee, ik woon in Gent.</span><small>Ні, я живу в Генті.</small>${icon('arrow')}</button></div><p class="life-feedback" role="status" aria-live="polite"></p></section></main>`}
function audio(){return `${learnHeader('Послухай і зрозумій','2 / 5')}<main class="learning audio"><span class="eyebrow">АУДІЮВАННЯ</span><h1>Спочатку послухай.<br>Потім обери.</h1><section class="audio-player">${sound('Відтворити фразу','large')}<div class="wave" aria-hidden="true">${Array.from({length:23},(_,i)=>`<i></i>`).join('')}</div><p>Можна прослухати ще раз</p></section><div class="answers">${['привіт','дякую','до завтра'].map((x,i)=>`<button class="answer" data-demo="Лише огляд компонента Audio, результат не зберігається."><span class="answer-index">${i+1}</span>${x}</button>`).join('')}</div>${route('home','До огляду '+icon('arrow'),'primary')}</main>`}
function review(){return `${learnHeader('Повторення','1 / 3')}<main class="learning review"><span class="eyebrow">СЛОВА, ЯКІ ВАРТО ПОВТОРИТИ</span><h1>Знайоме слово.<br>Нова впевненість.</h1><div class="review-card"><span class="tag">ПОВТОРЕННЯ ПОМИЛКИ</span><h2 lang="nl">hallo</h2><p>Згадай переклад, перш ніж відкрити відповідь.</p>${sound('Послухати')}<button class="secondary" id="reveal">Показати відповідь</button><p id="reviewAnswer" hidden><b>привіт</b> · Hallo, ik ben Anastasia.</p></div><div class="review-actions"><button class="secondary" data-demo="Демо повторення: результати не зберігаються.">${icon('repeat')}Ще повторю</button><button class="primary" data-demo="Демо успіху: алгоритм SRS не підключений.">${icon('check')}Згадав / згадала</button></div></main>`}
function render(){document.body.className='concept-'+concept+' view-'+screen;document.title=`${concept.toUpperCase()} — ${names[concept]} · ${screen} · TEST-027`;document.getElementById('app').innerHTML=`<div class="prototype-bar"><a href="index.html">${concept.toUpperCase()} / ${names[concept]}</a><span>Прототип · демодані</span></div>${({home,study,quiz,life,audio,review}[screen])()}`;bind();}
let noticeTimer;
function notice(text){const n=document.getElementById('notice');n.textContent=text;n.classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.classList.remove('visible'),3500)}
function go(s){screen=s;history.replaceState(null,'',`?concept=${concept}&screen=${s}`);render();window.scrollTo(0,0);document.querySelector('main h1, main h2')?.setAttribute('tabindex','-1');document.querySelector('main h1, main h2')?.focus({preventScroll:true})}
function bind(){
 document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>go(b.dataset.screen));
 document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>notice(b.dataset.demo));
 document.querySelector('#courseButton')?.addEventListener('click',()=>document.getElementById('courseDialog').showModal());
 document.querySelectorAll('[data-audio]').forEach(b=>b.onclick=()=>{b.classList.toggle('is-playing');b.setAttribute('aria-pressed',String(b.classList.contains('is-playing')));notice('Демо стану відтворення. Звук у прототипі не підключено.');setTimeout(()=>{b.classList.remove('is-playing');b.setAttribute('aria-pressed','false')},1800)});
 let selected=null,checked=false;const check=document.getElementById('checkAnswer');
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(checked)return;selected=+b.dataset.answer;document.querySelectorAll('[data-answer]').forEach(x=>x.classList.toggle('selected',x===b));check.disabled=false});
 if(check)check.onclick=()=>{if(checked){go('study');return}checked=true;const good=selected===1;document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(+b.dataset.answer===1)b.classList.add('correct');else if(+b.dataset.answer===selected)b.classList.add('wrong')});const f=document.getElementById('feedback');f.className='feedback '+(good?'success':'error');f.innerHTML=icon(good?'check':'repeat')+`<div><b>${good?'Саме так!':'Запам’ятай правильну відповідь'}</b><p><span lang="nl">hallo</span> — привіт</p></div>`;check.innerHTML='Далі '+icon('arrow')};
 document.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>{const good=b.dataset.reply==='correct';b.classList.add(good?'correct':'wrong');document.querySelector('.life-feedback').textContent=good?'Так починається знайомство. Це демонстрація відповіді.':'Запитання про ім’я: «Ja, ik ben Anastasia.» Це демонстрація помилки.'});
 document.querySelector('#reveal')?.addEventListener('click',e=>{document.getElementById('reviewAnswer').hidden=false;e.currentTarget.hidden=true});
}
document.querySelector('#closeCourse').onclick=()=>document.getElementById('courseDialog').close();document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>notice('Вибір '+b.dataset.course+' показано лише для огляду компонента. Дані курсу не змінені.'));
render();
